// Mirrors zarrow's benchmarks/*_benchmark.zig default configs, shape for shape.
use arrow::array::*;
use arrow::compute::{concat, filter, take};
use arrow::datatypes::*;
use arrow::ipc::reader::StreamReader;
use arrow::ipc::writer::{IpcWriteOptions, StreamWriter};
use arrow::ipc::CompressionType;
use arrow::record_batch::RecordBatch;
use std::io::Cursor;
use std::sync::Arc;
use std::time::Instant;

const NAMES: [&str; 4] = ["alpha", "beta", "gamma", "delta-long-name"];

fn report(name: &str, rows: usize, iters: usize, elapsed_ns: u128, checksum: u64) {
    let total = (rows * iters) as f64;
    println!(
        "benchmark={name} rows={rows} iterations={iters} elapsed_ns={elapsed_ns} rows_per_sec={:.2} ns_per_row={:.2} checksum={checksum}",
        total * 1e9 / elapsed_ns as f64,
        elapsed_ns as f64 / total
    );
}

fn build_sources(rows: usize) -> (Int32Array, StringArray) {
    let mut ints = Int32Builder::with_capacity(rows);
    let mut strs = StringBuilder::with_capacity(rows, rows * 8);
    for i in 0..rows {
        if i % 7 == 0 {
            ints.append_null();
            strs.append_null();
        } else {
            ints.append_value(i as i32);
            strs.append_value(NAMES[i & 3]);
        }
    }
    (ints.finish(), strs.finish())
}

fn bench_primitive_builder(rows: usize, iters: usize) {
    let mut builder = Int32Builder::with_capacity(rows);
    let mut checksum: i64 = 0;
    let t = Instant::now();
    for iter in 0..iters {
        for i in 0..rows {
            let v = ((i + iter) % 1024) as i32;
            builder.append_value(v);
            checksum += v as i64;
        }
        let arr = builder.finish();
        std::hint::black_box(&arr);
    }
    report("primitive_builder", rows, iters, t.elapsed().as_nanos(), checksum as u64);
}

fn bench_concat(rows: usize, iters: usize) {
    let (ints, strs) = build_sources(rows);
    let part_rows = 16;
    let part_count = (rows + part_rows - 1) / part_rows;
    let int_parts: Vec<ArrayRef> = (0..part_count)
        .map(|p| {
            let s = p * part_rows;
            Arc::new(ints.slice(s, part_rows.min(rows - s))) as ArrayRef
        })
        .collect();
    let str_parts: Vec<ArrayRef> = (0..part_count)
        .map(|p| {
            let s = p * part_rows;
            Arc::new(strs.slice(s, part_rows.min(rows - s))) as ArrayRef
        })
        .collect();
    let ir: Vec<&dyn Array> = int_parts.iter().map(|a| a.as_ref()).collect();
    let sr: Vec<&dyn Array> = str_parts.iter().map(|a| a.as_ref()).collect();
    let mut checksum = 0usize;
    let t = Instant::now();
    for _ in 0..iters {
        let io = concat(&ir).unwrap();
        let so = concat(&sr).unwrap();
        checksum += io.len() + so.null_count();
    }
    report("concat", rows, iters, t.elapsed().as_nanos(), checksum as u64);
}

fn bench_filter(rows: usize, iters: usize) {
    let (_ints, strs) = build_sources(rows);
    let mut pb = BooleanBuilder::with_capacity(rows);
    for i in 0..rows {
        if i % 11 == 0 {
            pb.append_null()
        } else {
            pb.append_value((i * 7919) % 2 == 0)
        }
    }
    let pred = pb.finish();
    let mut checksum = 0usize;
    let t = Instant::now();
    for _ in 0..iters {
        let out = filter(&strs, &pred).unwrap();
        checksum += out.len();
    }
    report("filter", rows, iters, t.elapsed().as_nanos(), checksum as u64);
}

fn bench_take(rows: usize, iters: usize) {
    let mut b = Int32Builder::with_capacity(rows);
    for i in 0..rows {
        if i % 7 == 0 {
            b.append_null()
        } else {
            b.append_value(i as i32)
        }
    }
    let source = b.finish();
    let indices = UInt64Array::from_iter_values((0..rows).map(|i| ((i * 7919 + 13) % rows) as u64));
    let mut checksum: i64 = 0;
    let t = Instant::now();
    for iter in 0..iters {
        let out = take(&source, &indices, None).unwrap();
        let taken = out.as_primitive::<Int32Type>();
        let k = iter % rows;
        if !taken.is_null(k) {
            checksum += taken.value(k) as i64
        }
    }
    report("take", rows, iters, t.elapsed().as_nanos(), checksum as u64);
}

fn bench_ipc_compressed(rows: usize, iters: usize) {
    let schema = Arc::new(Schema::new(vec![
        Field::new("id", DataType::Int32, true),
        Field::new("name", DataType::Utf8, true),
    ]));
    let (ints, strs) = build_sources(rows);
    let batch = RecordBatch::try_new(schema.clone(), vec![Arc::new(ints), Arc::new(strs)]).unwrap();
    let opts = IpcWriteOptions::default()
        .try_with_compression(Some(CompressionType::ZSTD))
        .unwrap();
    let mut checksum = 0usize;
    let t = Instant::now();
    for _ in 0..iters {
        let mut sink = Vec::with_capacity(rows * 16 + 4096);
        {
            let mut w = StreamWriter::try_new_with_options(&mut sink, &schema, opts.clone()).unwrap();
            w.write(&batch).unwrap();
            w.finish().unwrap();
        }
        let r = StreamReader::try_new(Cursor::new(&sink), None).unwrap();
        for rb in r {
            checksum += rb.unwrap().num_rows();
        }
    }
    report("ipc_compressed", rows, iters, t.elapsed().as_nanos(), checksum as u64);
}

fn bench_ipc_roundtrip(rows: usize, iters: usize) {
    const BATCHES: usize = 8;
    let schema = Arc::new(Schema::new(vec![
        Field::new("id", DataType::Int32, true),
        Field::new("value", DataType::Int64, false),
        Field::new("ok", DataType::Boolean, false),
        Field::new("name", DataType::Utf8, false),
    ]));
    let mut id = Int32Builder::with_capacity(rows);
    let mut value = Int64Builder::with_capacity(rows);
    let mut ok = BooleanBuilder::with_capacity(rows);
    let mut name = StringBuilder::with_capacity(rows, rows * 8);
    for i in 0..rows {
        if i % 7 == 0 {
            id.append_null()
        } else {
            id.append_value(i as i32)
        }
        value.append_value((i * 3) as i64);
        ok.append_value(i & 1 == 0);
        name.append_value(NAMES[i & 3]);
    }
    let batch = RecordBatch::try_new(
        schema.clone(),
        vec![
            Arc::new(id.finish()),
            Arc::new(value.finish()),
            Arc::new(ok.finish()),
            Arc::new(name.finish()),
        ],
    )
    .unwrap();
    let mut checksum = 0usize;
    let (mut write_ns, mut read_ns) = (0u128, 0u128);
    for _ in 0..iters {
        let mut sink = Vec::with_capacity(rows * BATCHES * 32 + 4096);
        let t = Instant::now();
        {
            let mut w = StreamWriter::try_new(&mut sink, &schema).unwrap();
            for _ in 0..BATCHES {
                w.write(&batch).unwrap();
            }
            w.finish().unwrap();
        }
        write_ns += t.elapsed().as_nanos();
        let t = Instant::now();
        // arrow-rs StreamReader over a Cursor copies buffers (no zero-copy stream API).
        let r = StreamReader::try_new(Cursor::new(&sink), None).unwrap();
        for rb in r {
            checksum += rb.unwrap().num_rows();
        }
        read_ns += t.elapsed().as_nanos();
    }
    let total = (rows * iters * BATCHES) as f64;
    println!(
        "benchmark=ipc_roundtrip rows={rows} iterations={iters} batches_per_iter={BATCHES} elapsed_ns={} write_ns={write_ns} read_ns={read_ns} rows_per_sec={:.2} ns_per_row={:.2} checksum={checksum}",
        write_ns + read_ns,
        total * 1e9 / (write_ns + read_ns) as f64,
        (write_ns + read_ns) as f64 / total
    );
}

fn main() {
    let which = std::env::args().nth(1).unwrap_or_default();
    match which.as_str() {
        "primitive_builder" => bench_primitive_builder(200_000, 80),
        "concat" => bench_concat(200_000, 80),
        "filter" => bench_filter(200_000, 80),
        "take" => bench_take(200_000, 80),
        "ipc_compressed" => bench_ipc_compressed(200_000, 80),
        "ipc_roundtrip" => bench_ipc_roundtrip(20_000, 50),
        _ => eprintln!("usage: rsbench <name>"),
    }
}

