62	+const CountingAllocator = struct {
63	+    parent: Allocator,
64	+    live: usize = 0,
65	+
66	+    fn allocator(self: *CountingAllocator) Allocator {
67	+        return .{ .ptr = self, .vtable = &.{ .alloc = alloc, .resize = resize, .remap = remap, .free = free } };
68	+    }
69	+
70	+    fn charge(self: *CountingAllocator, old: usize, new: usize) void {
71	+        if (new > old and self.live + (new - old) > alloc_cap)
72	+            std.debug.panic("fuzz-oom: allocation of {d} bytes with {d} live exceeds cap {d}", .{ new - old, self.live, alloc_cap });
73	+    }
74	+
75	+    fn alloc(ctx: *anyopaque, len: usize, a: std.mem.Alignment, ra: usize) ?[*]u8 {
76	+        const self: *CountingAllocator = @ptrCast(@alignCast(ctx));
77	+        self.charge(0, len);
78	+        const p = self.parent.rawAlloc(len, a, ra) orelse return null;
79	+        self.live += len;
80	+        return p;
81	+    }
82	+
83	+    fn resize(ctx: *anyopaque, m: []u8, a: std.mem.Alignment, n: usize, ra: usize) bool {
84	+        const self: *CountingAllocator = @ptrCast(@alignCast(ctx));
85	+        self.charge(m.len, n);
86	+        if (!self.parent.rawResize(m, a, n, ra)) return false;
87	+        self.live = self.live - m.len + n;
88	+        return true;
89	+    }
90	+
91	+    fn remap(ctx: *anyopaque, m: []u8, a: std.mem.Alignment, n: usize, ra: usize) ?[*]u8 {
92	+        const self: *CountingAllocator = @ptrCast(@alignCast(ctx));
93	+        self.charge(m.len, n);
94	+        const p = self.parent.rawRemap(m, a, n, ra) orelse return null;
95	+        self.live = self.live - m.len + n;
96	+        return p;
97	+    }
98	+
99	+    fn free(ctx: *anyopaque, m: []u8, a: std.mem.Alignment, ra: usize) void {
100	+        const self: *CountingAllocator = @ptrCast(@alignCast(ctx));
101	+        self.parent.rawFree(m, a, ra);
102	+        self.live -= m.len;
103	+    }
104	+};
