346	+fn childTypes(a: Allocator, dt: DataType) Allocator.Error![]const *const DataType {
347	+    const one = struct {
348	+        fn of(al: Allocator, t: *const DataType) Allocator.Error![]const *const DataType {
349	+            const s = try al.alloc(*const DataType, 1);
350	+            s[0] = t;
351	+            return s;
352	+        }
353	+    }.of;
354	+    return switch (dt) {
355	+        .list, .large_list => |l| one(a, l.value_field.data_type),
356	+        .list_view, .large_list_view => |l| one(a, l.value_field.data_type),
357	+        .fixed_size_list => |l| one(a, l.value_field.data_type),
358	+        .struct_ => |s| fieldTypes(a, s.fields),
359	+        .sparse_union, .dense_union => |u| fieldTypes(a, u.fields),
360	+        .map => |m| blk: {
361	+            const fields = try a.alloc(Field, 2);
362	+            fields[0] = m.key_field;
363	+            fields[1] = m.item_field;
