370	+            const ends = try a.create(DataType);
371	+            ends.* = intDataType(r.run_end_type);
372	+            s[0] = ends;
373	+            s[1] = r.value_type;
374	+            break :blk s;
375	+        },
376	+        .extension => |e| childTypes(a, e.storage_type.*),
377	+        else => &.{},
