398	+fn genBuffer(in: *Input, rng: std.Random, a: Allocator, total: usize) Allocator.Error!zarrow.SharedBuffer {
399	+    const mode = in.byte() % 8;
400	+    const n = switch (mode) {
401	+        0 => return zarrow.SharedBuffer.empty,
402	+        1 => in.below(257),
403	+        else => (total + 1) * 32,
404	+    };
405	+    const buf = try a.alignedAlloc(u8, .fromByteUnits(64), n);
406	+    switch (mode) {
407	+        1 => rng.bytes(buf),
408	+        2 => @memset(buf, 0),
409	+        3 => @memset(buf, 0xff),
410	+        4, 5 => { // ascending offsets / run ends (i32 or i64) with small steps
411	+            const step = in.byte() % 4;
412	+            var v: i64 = 0;
413	+            if (mode == 4) {
414	+                for (std.mem.bytesAsSlice(i32, buf)) |*x| {
415	+                    x.* = @intCast(v);
416	+                    v += rng.uintAtMost(u8, step);
417	+                }
418	+            } else for (std.mem.bytesAsSlice(i64, buf)) |*x| {
419	+                x.* = v;
420	+                v += rng.uintAtMost(u8, step);
421	+            }
422	+        },
423	+        6 => for (buf) |*x| { // small ids (union type ids, dictionary indices)
424	+            x.* = rng.uintLessThan(u8, 4);
425	+        },
426	+        else => rng.bytes(buf),
427	+    }
428	+    return zarrow.SharedBuffer.fromSlice(buf);
429	+}
