431	+fn genArray(in: *Input, rng: std.Random, a: Allocator, gpa: Allocator, dt: *const DataType, depth: u32) Allocator.Error!ArrayRef {
432	+    const length = in.below(65);
433	+    const offset = in.below(17);
434	+    const total = length + offset;
435	+    const null_count: ?usize = switch (in.byte() % 4) {
436	+        0 => null,
437	+        1 => 0,
438	+        2 => length,
439	+        else => in.below(70),
440	+    };
441	+    var n_buffers = bufferCount(dt.*);
442	+    if (in.byte() % 8 == 0) n_buffers = in.below(5);
443	+    const buffers = try a.alloc(zarrow.SharedBuffer, n_buffers);
444	+    for (buffers) |*b| b.* = try genBuffer(in, rng, a, total);
445	+
446	+    var child_types = try childTypes(a, dt.*);
447	+    if (in.byte() % 16 == 0) child_types = child_types[0 .. child_types.len - @min(child_types.len, 1)];
448	+    const children = try a.alloc(ArrayRef, if (depth < 4) child_types.len else 0);
449	+    var made: usize = 0;
450	+    defer for (children[0..made]) |*c| c.release();
451	+    for (children) |*c| {
452	+        c.* = try genArray(in, rng, a, gpa, child_types[made], depth + 1);
453	+        made += 1;
454	+    }
455	+    var dictionary: ?ArrayRef = null;
456	+    defer if (dictionary) |*d| d.release();
457	+    if (dt.* == .dictionary and depth < 4 and in.byte() % 8 != 0)
458	+        dictionary = try genArray(in, rng, a, gpa, dt.dictionary.value_type, depth + 1);
459	+
460	+    return ArrayRef.fromBorrowed(gpa, .{
461	+        .data_type = dt.*,
462	+        .length = length,
463	+        .offset = offset,
464	+        .null_count = null_count,
465	+        .buffers = buffers,
466	+        .children = children,
467	+        .dictionary = dictionary,
468	+    });
