967	+        const base = std.fs.path.basename(path);
968	+        if (for ([_][]const u8{ "gen-", "regress-", "at-stream-", "at-tensor-" }) |p| {
969	+            if (std.mem.startsWith(u8, base, p)) break true;
970	+        } else false) continue;
971	+        const bytes = cwd.readFileAlloc(io, path, a, .limited(max_input_len)) catch continue;
972	+        if (runOne(.@"ipc-stream", gpa, bytes).err != null) continue;
973	+        for ([_]?zarrow.IpcBodyCompressionCodec{ null, .lz4_frame, .zstd }) |codec| {
974	+            for ([_]bool{ false, true }) |as_file| {
975	+                const encoded = (if (as_file) transcode(gpa, bytes, codec, true) else transcode(gpa, bytes, codec, false)) catch continue;
976	+                defer gpa.free(encoded);
977	+                const check: Target = if (as_file) .@"ipc-file" else .@"ipc-stream";
978	+                if (runOne(check, gpa, encoded).err != null or encoded.len > 16 << 10) continue;
979	+                const hex = hexName(encoded);
980	+                const name = try std.fmt.allocPrint(a, "{s}/gen-{s}-{s}.bin", .{
981	+                    if (as_file) file_dir else stream_dir,
