993	+fn transcode(gpa: Allocator, bytes: []const u8, codec: ?zarrow.IpcBodyCompressionCodec, comptime as_file: bool) ![]u8 {
994	+    var fixed: std.Io.Reader = .fixed(bytes);
995	+    var reader = zarrow.IpcStreamReader.init(gpa, &fixed);
996	+    defer reader.deinit();
997	+    const schema = try reader.readSchema();
998	+    var out: std.Io.Writer.Allocating = .init(gpa);
999	+    errdefer out.deinit();
1000	+    const options: zarrow.IpcStreamWriterOptions = .{ .body_compression = codec };
1001	+    var writer = if (as_file)
1002	+        try zarrow.IpcFileWriter.initWithOptions(gpa, &out.writer, options)
1003	+    else
1004	+        zarrow.IpcStreamWriter.initWithOptions(gpa, &out.writer, options);
1005	+    defer writer.deinit();
1006	+    try writer.writeSchema(schema);
1007	+    while (try reader.nextRecordBatch()) |batch_value| {
1008	+        var batch = batch_value;
1009	+        defer batch.deinit();
1010	+        try writer.writeRecordBatch(batch);
1011	+        if (batch.numRows() > 2 and !as_file) { // sliced batches exercise non-zero offsets
1012	+            var sliced = try batch.slice(1, batch.numRows() - 2);
1013	+            defer sliced.deinit();
1014	+            try writer.writeRecordBatch(sliced);
1015	+        }
1016	+    }
1017	+    try writer.writeEnd();
1018	+    return out.toOwnedSlice();
1019	+}
